export const BODY: string = "\n<p>تصویر کو 500KB تک کمپریس کرنا سب سے آسان کمپریشن کام ہے۔ بجٹ فراخ ہے، کوالٹی اونچی رہتی ہے اور طریقہ تقریباً دو منٹ میں مکمل ہوتا ہے۔</p>\n<p>یہ رہنما ہر مرحلہ بتاتا ہے۔ آپ ماخذ فائل تیار کریں گے، درست فارمیٹ چنیں گے، کمپریشن چلائیں گے اور استعمال سے پہلے نتیجہ کی تصدیق کریں گے۔</p>\n<p>یہ پورٹ فولیو، سلائیڈ ڈیک، گیلری اور اونچی کوالٹی والی ویب تصویروں کے لیے کام کرتا ہے، لیپ ٹاپ پر بھی اور فون پر بھی۔</p>\n<h2 id=\"what-you-need\">شروع کرنے سے پہلے کیا چاہیے</h2>\n<p>آپ کو دستیاب بہترین کوالٹی میں اصل تصویر چاہیے۔ کیمرے کی تصویر مثالی ہے، چیٹ ایپ سے آگے بھیجی گئی کاپی پہلے سے خراب ہوتی ہے۔</p>\n<p>کمپریس کرنے سے پہلے منزل کے اصول جانچیں۔ زیادہ سے زیادہ فائل سائز، مطلوبہ ابعاد اور قبول شدہ فارمیٹ نوٹ کریں۔</p>\n<p>طے کریں کہ تصویر کس لیے ہے۔ پورٹ فولیو شاٹ کو زیادہ سے زیادہ تفصیل چاہیے، جبکہ سلائیڈ پس منظر میں تھوڑی نرمی چل جاتی ہے۔</p>\n<h2 id=\"step-1-open\">مرحلہ 1: 500KB ٹول کھولیں</h2>\n<p>براؤزر میں <a href=\"/ur/tasveer-compress-karein-500kb-tak/\">Compress Image to 500KB ٹول</a> کھولیں۔ اکاؤنٹ یا انسٹال کی ضرورت نہیں ہے، اور صفحہ جلد کھلتا ہے۔</p>\n<p>ٹول مکمل طور پر آپ کے آلے پر چلتا ہے۔ آپ کی تصویریں مقامی طور پر پروسیس ہوتی ہیں اور کبھی کسی سرور پر اپ لوڈ نہیں ہوتیں، جو کلائنٹ کے کام کے لیے اہم ہے۔</p>\n<p>اگر آپ فون پر ہیں تو صفحہ ویسے ہی کام کرتا ہے۔ اپ لوڈ والے حصے پر ٹیپ کریں اور گیلری سے تصویر چنیں۔ اگر آپ اکثر تصویریں کمپریس کرتے ہیں تو صفحہ بک مارک کر لیں۔</p>\n<h2 id=\"step-2-upload\">مرحلہ 2: اپنی تصویر اپ لوڈ کریں</h2>\n<p>فائل کو صفحے پر گھسیٹ دیں یا براؤز کرنے کے لیے ٹیپ کریں۔ JPG، PNG، WebP اور HEIC فائلیں قبول ہوتی ہیں، ہر ایک 25 MB تک۔</p>\n<p>اپنے پاس موجود بہترین کوالٹی والا نسخہ اپ لوڈ کریں۔ 24 میگا پکسل اصل کمپریسر کو چھوٹی کاپی سے کہیں زیادہ مواد دیتا ہے۔</p>\n<p>بیچ کے لیے کئی فائلیں ایک ساتھ چنیں۔ ہر ایک 500KB تک کمپریس ہوتی ہے، اور آپ انہیں ZIP کے طور پر ایک ساتھ ڈاؤن لوڈ کرتے ہیں۔</p>\n<h2 id=\"step-3-format\">مرحلہ 3: آؤٹ پٹ فارمیٹ چنیں</h2>\n<p>تصویروں کے لیے JPG محفوظ پہلے سے طے شدہ انتخاب ہے۔ یہ ہر جگہ قبول ہوتا ہے اور 500KB پر بہترین نتائج دیتا ہے۔</p>\n<p>اگر منزل قبول کرتی ہو اور آپ تیز ترین نتیجہ چاہتے ہوں تو WebP چنیں۔ WebP اسی سائز پر کنارے تھوڑے صاف رکھتا ہے۔</p>\n<p>PNG صرف فلیٹ رنگ، تیز لکیروں یا شفافیت والے گرافکس کے لیے رکھیں۔ PNG میں محفوظ تصویر 500KB تک پہنچنے میں مشکل کرے گی۔</p>\n<h2 id=\"step-4-run\">مرحلہ 4: کمپریشن چلائیں</h2>\n<p>ٹول خودکار بائنری کوالٹی تلاش چلاتا ہے۔ یہ کوالٹی سطحیں آزماتا ہے جب تک وہ سب سے اونچی سطح نہ مل جائے جو 500KB سے نیچے فٹ ہو۔</p>\n<p>آپ کو کوالٹی فیصد چننے کی ضرورت نہیں ہے۔ تلاش آپ کی مخصوص تصویر کے لیے بہترین عدد ڈھونڈتی ہے، جو اکثر گول عدد نہیں ہوتا۔</p>\n<p>Under 500KB والی تصدیق تلاش کریں۔ یہ بیج بتاتا ہے کہ فائل حد پاس کر گئی ہے اور استعمال کے لیے تیار ہے۔ اگر ہدف چھوٹ گیا تو فارمیٹ JPG کریں۔</p>\n<h2 id=\"step-5-preview\">مرحلہ 5: نتیجہ احتیاط سے پیش نظارہ دیکھیں</h2>\n<p>ڈاؤن لوڈ سے پہلے کمپریس شدہ تصویر مکمل سائز میں پیش نظارہ دیکھیں۔ چھوٹا تھمب نیل وہ مسائل چھپاتا ہے جو مکمل سائز پر واضح ہوتے ہیں۔</p>\n<p>پہلے باریک تفصیل جانچیں۔ کپڑے کی بناوٹ، بالوں کی لکیریں اور چھپے لیبل سب سے پہلے نرم ہوتے ہیں۔</p>\n<p>پھر متن جانچیں۔ تصویر میں کوئی بھی لفظ پڑھنے کے قابل رہنا چاہیے، خاص طور پر سلائیڈ، انفوگرافک اور سرٹیفکیٹ میں۔</p>\n<h2 id=\"step-6-download\">مرحلہ 6: ڈاؤن لوڈ کریں اور ترتیب دیں</h2>\n<p>فائل ڈاؤن لوڈ کریں۔ اس کا نام اسے 500KB والا نسخہ ظاہر کرے گا، اس لیے یہ اصل سے الجھے گی نہیں۔</p>\n<p>اپنے آلے پر فائل سائز جانچیں۔ یہ 500KB سے تھوڑا نیچے پڑھنا چاہیے، عام طور پر 498KB سے 499.9KB کے درمیان۔</p>\n<p>کمپریس شدہ کاپی اصل کے ساتھ رکھیں، اس کی جگہ نہیں۔ دونوں رکھنے کا مطلب ہے کہ آپ ہمیشہ مختلف ترتیبات سے دوبارہ آزما سکتے ہیں۔</p>\n<h2 id=\"fixing-problems\">عام مسائل کا حل</h2>\n<p>اگر تصویر دھندلی لگے تو ماخذ پہلے سے بہت چھوٹا ہو سکتا ہے۔ بڑے اصل سے شروع کریں اور دوبارہ کمپریس کریں۔</p>\n<p>اگر ہدف چھوٹ گیا تو JPG پر جائیں اور اسکیلنگ کی اجازت دیں۔ یہ دو تبدیلیاں 500KB پر زیادہ تر ناکامیاں حل کر دیتی ہیں۔</p>\n<p>اگر رنگ غلط لگیں تو جانچیں کہ تصویر کا پس منظر شفاف تو نہیں تھا۔ شفاف PNG کو JPG میں بدلنے سے پس منظر سفید بھر جاتا ہے۔</p>\n<h2 id=\"portfolio-workflow\">ورک فلو: پورٹ فولیو سیٹ</h2>\n<p>پورٹ فولیو کی تصویریں جمع کریں اور انہیں ایک بیچ کے طور پر اپ لوڈ کریں۔ ہر ایک کوالٹی زیادہ سے زیادہ رکھتے ہوئے 500KB تک کمپریس ہوتی ہے۔</p>\n<p>زیادہ سے زیادہ مطابقت کے لیے JPG استعمال کریں۔ پورٹ فولیو پلیٹفارم ہر جگہ JPG قبول کرتے ہیں، اور 500KB پر اس کی کوالٹی بہترین ہوتی ہے۔</p>\n<p>بیچ کے تین یا چار نتائج پیش نظارہ دیکھیں، صرف پہلا نہیں۔ اچھے نتائج میں ایک خراب نتیجہ چھپ سکتا ہے۔</p>\n<h2 id=\"deck-workflow\">ورک فلو: سلائیڈ ڈیک</h2>\n<p>شروع کرنے سے پہلے ڈیک کی تمام تصویریں جمع کریں۔ انہیں ساتھ کمپریس کرنے سے تمام سلائیڈوں میں کوالٹی مستقل رہتی ہے۔</p>\n<p>بیچ کو 500KB ٹول پر اپ لوڈ کریں اور فارمیٹ JPG رکھیں۔ ای میل سے شیئر ہونے والے ڈیک کو ایسی فائلیں چاہییں جو ہر نظام کھول سکے۔</p>\n<p>وہ تصویریں پیش نظارہ دیکھیں جو سب سے بڑی دکھائی جائیں گی۔ مکمل سلائیڈ پس منظر کو کونے والے چھوٹے تھمب نیل سے زیادہ احتیاط چاہیے ہوتی ہے۔</p>\n<h2 id=\"phone-workflow\">ورک فلو: فون یا ٹیبلٹ پر</h2>\n<p>موبائل براؤزر میں ٹول کھولیں اور اپ لوڈ والے حصے پر ٹیپ کریں۔ گیلری سے اصل تصویر چنیں۔</p>\n<p>آئی فون کی تصویریں HEIC فائلیں ہو سکتی ہیں۔ انہیں سیدھا اپ لوڈ کریں، ٹول کمپریشن کے دوران تبدیلی سنبھال لیتا ہے۔</p>\n<p>نتیجہ اسکرین پر پیش نظارہ دیکھیں، پھر زوم کرنے کے لیے چٹکی بھر کر دیکھیں۔ ڈاؤن لوڈ سے پہلے باریک تفصیل اور کوئی بھی متن جانچیں۔</p>\n<h2 id=\"checking-dimensions-500kb\">کمپریشن کے بعد ابعاد جانچنا</h2>\n<p>فائل سائز صرف آدھی کہانی ہے۔ کچھ منزلیں پکسل ابعاد بھی جانچتی ہیں، اور غلط سائز والی 500KB فائل پھر بھی ناکام ہوتی ہے۔</p>\n<p>ڈاؤن لوڈ شدہ فائل کی خصوصیات کھول کر پکسل گنتی پڑھیں۔ اپ لوڈ سے پہلے اسے منزل کے اصولوں سے ملائیں۔</p>\n<p>اگر ٹول نے تصویر چھوٹی کر دی تو ابعاد اصل سے چھوٹے ہوں گے۔ یہ معمول ہے جب صرف کوالٹی سے 500KB تک نہیں پہنچا جا سکا۔</p>\n<h2 id=\"infographics-500kb\">500KB پر انفوگرافک اور چارٹ</h2>\n<p>انفوگرافک مشکل تصویریں ہوتی ہیں۔ ان میں متن، باریک لکیریں اور فلیٹ رنگ ملے ہوتے ہیں، اور ہر جز کو تیز رہنے کے لیے ڈیٹا چاہیے ہوتا ہے۔</p>\n<p>500KB پر زیادہ تر انفوگرافک مکمل پڑھنے کے قابل رہتے ہیں۔ چھوٹے لیبل جو 100KB پر دھندلے ہوتے ہیں، اس سائز پر صاف رہتے ہیں۔</p>\n<p>PNG انفوگرافک کے لیے دلکش ہے کیونکہ یہ لکیریں بالکل رکھتا ہے۔ مگر تفصیلی انفوگرافک PNG میں 500KB تک پہنچنے کے لیے ابعاد میں کٹوتی مانگ سکتا ہے۔</p>\n<h2 id=\"sharing-500kb\">ای میل اور چیٹ سے 500KB تصویریں شیئر کرنا</h2>\n<p>ای میل نظام اکثر منسلکات کو 20 MB یا 25 MB تک محدود کرتے ہیں۔ 500KB تصویروں کا سیٹ ان حدوں میں آرام سے فٹ ہو جاتا ہے۔</p>\n<p>چیٹ ایپس بھیجتے وقت تصویریں دوبارہ کمپریس کرتی ہیں۔ صاف 500KB فائل سے شروع کرنا ایپ کو کام کرنے کے لیے اچھا ماخذ دیتا ہے۔</p>\n<p>کلائنٹ ثبوت کے لیے 500KB اچھا شیئرنگ سائز ہے۔ کلائنٹ کام صاف دیکھتا ہے، بغیر بڑی فائلیں ڈاؤن لوڈ ہونے کا انتظار کیے۔</p>\n<h2 id=\"cropping-500kb\">500KB تک کمپریس کرنے سے پہلے کراپ کرنا</h2>\n<p>سخت کراپ کسی بھی تصویر کو مضبوط اور چھوٹا بنا دیتا ہے۔ خالی پس منظر ہٹانے سے موضوع کو 500KB بجٹ کا زیادہ حصہ ملتا ہے۔</p>\n<p>موضوع کو ارد گرد تھوڑے مارجن کے ساتھ درمیان میں رکھیں۔ بہت سخت کراپ تنگ محسوس ہوتا ہے، جبکہ بہت ڈھیلا کراپ کلو بائٹ ضائع کرتا ہے۔</p>\n<p>اصل فائل پر کراپ کریں، کمپریس شدہ کاپی پر نہیں۔ کمپریشن کے بعد کراپ کرنے سے کوالٹی دو بار ضائع ہوتی ہے۔</p>\n<h2 id=\"troubleshooting-500kb\">خرابی دور کرنے کی چیک لسٹ</h2>\n<p>جب کچھ غلط ہو تو چیک لسٹ ترتیب سے دیکھیں۔ زیادہ تر مسائل کی وجہ سادہ ہوتی ہے اور حل بھی سادہ ہوتا ہے۔</p>\n<p>پہلے ماخذ فائل جانچیں۔ چھوٹی یا خراب اصل کسی بھی ترتیب سے اچھا 500KB نتیجہ نہیں دے سکتی۔</p>\n<p>دوسرے، فارمیٹ جانچیں۔ PNG تصویریں اور شفاف تصویریں 500KB پر ہدف چھوٹنے کی سب سے عام وجہ ہیں۔</p>\n<h2 id=\"colour-accuracy-500kb-howto\">آپ کی 500KB فائلوں میں رنگ کی درستگی</h2>\n<p>مصنوعات کی تصویروں اور تخلیقی کام کے لیے رنگ کی درستگی اہم ہے۔ تصویر سے مختلف رنگ والی قمیض ملنے پر خریدار اسے واپس کر دے گا۔</p>\n<p>500KB پر رنگ وفادار رہتے ہیں۔ کمپریشن میلان کو ہلکا سادہ کرتی ہے، مگر الگ رنگ الگ رہتے ہیں۔</p>\n<p>جب ممکن ہو مصنوعات قدرتی روشنی میں فوٹوگراف کریں۔ مصنوعی روشنی کمپریشن شروع ہونے سے پہلے رنگ بدل دیتی ہے، اور ٹول اسے ٹھیک نہیں کر سکتا۔</p>\n<h2 id=\"archiving-howto-500kb\">آرکائیونگ: 500KB آرکائیو سائز نہیں ہے</h2>\n<p>500KB فائل ڈیلیوری فارمیٹ ہے، آرکائیو فارمیٹ نہیں۔ یہ شیئر کرنے کے لیے بنائی گئی ہے، ہمیشہ رکھنے کے لیے نہیں۔</p>\n<p>اصل کو مکمل کوالٹی پر آرکائیو کریں۔ 500KB کاپی کو نظر آنے والے نقصان کے بغیر بڑا، دوبارہ پرنٹ یا دوبارہ ایڈٹ نہیں کیا جا سکتا۔</p>\n<p>شائع کرنے اور شیئر کرنے کے لیے 500KB کاپیاں استعمال کریں۔ یہ جلد کھلتی ہیں، اپ لوڈ حدیں پاس کرتی ہیں اور اسکرین پر اچھی لگتی ہیں۔</p>\n<h2 id=\"measuring-howto-500kb\">کمپریشن کے بعد کامیابی ناپنا</h2>\n<p>کامیابی ناپنا آسان ہے: فائل 500KB سے نیچے ہے، تصویر صاف لگتی ہے اور منزل اسے بغیر شکایت قبول کر لیتی ہے۔</p>\n<p>اصل اور کمپریس شدہ سائز کا موازنہ کر کے بچت دیکھیں۔ 5 MB تصویر کو 500KB تک کم کرنا نوے فیصد بچت ہے، جو نوٹ کرنے والا عدد ہے۔</p>\n<p>شائع کرنے کے بعد صفحہ یا ڈیک جانچیں۔ تصویریں جلد کھلنی چاہیں اور تیز دکھنی چاہیں، بغیر بینڈنگ یا نرمی کے۔</p>\n<p>500KB کوالٹی کا پس منظر <a href=\"/ur/blog/tasveer-500kb-tak-compress-karein-rehnumai/\">Compress Image to 500KB: Complete Guide</a> میں پڑھیں۔ 1 MB سے موازنے کے لیے <a href=\"/ur/blog/500kb-vs-1mb-tasveer-quality/\">500KB vs 1MB: Image Quality for Web and Print</a> دیکھیں۔ اگر چھوٹی فائل چاہیے تو <a href=\"/ur/tasveer-compress-karein-200kb-tak/\">200KB کمپریسر</a> اگلا مرحلہ ہے۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"کوالٹی کھوئے بغیر تصویر 500KB تک کیسے کمپریس کروں؟","answer":"اصل ہائی کوالٹی تصویر استعمال کریں اور بائنری تلاش کو وہ بہترین کوالٹی ڈھونڈنے دیں جو 500KB سے نیچے فٹ ہو۔ اس فراخ سائز پر زیادہ تر تصویریں مکمل ریزولوشن رکھتی ہیں اور اصل جیسی دکھائی دیتی ہیں۔ ڈاؤن لوڈ سے پہلے نتیجہ مکمل سائز میں پیش نظارہ دیکھیں۔"},{"question":"کیا بیس تصویریں ایک بیچ میں 500KB تک کمپریس کر سکتا ہوں؟","answer":"جی ہاں۔ تمام بیس فائلیں شامل کریں اور ہر ایک 500KB سے نیچے کمپریس ہوتی ہے، پھر انہیں ZIP کے طور پر ایک ساتھ ڈاؤن لوڈ کریں۔ یہ پورٹ فولیو اور سلائیڈ ڈیک کے لیے مثالی ہے۔ پورا بیچ ڈاؤن لوڈ کرنے سے پہلے چند نتائج پیش نظارہ دیکھیں۔"},{"question":"میری ڈاؤن لوڈ شدہ فائل بالکل 500KB کی بجائے 498KB کیوں ہے؟","answer":"ٹول جان بوجھ کر حد سے تھوڑا نیچے ہدف رکھتا ہے تاکہ نظاموں کے درمیان بائٹ گول کرنے کے فرق کے لیے حفاظتی مارجن رہے۔ آپ کے آلے پر 500KB پڑھنے والی فائل دراصل 500.4KB ہو سکتی ہے، جسے سخت نظام مسترد کر دے گا۔"},{"question":"اگر میری PNG 500KB سے نیچے نہ جائے تو کیا کروں؟","answer":"آؤٹ پٹ فارمیٹ JPG یا WebP پر بدلیں، کیونکہ PNG تصویریں غیر مؤثر انداز میں محفوظ کرتا ہے۔ تفصیلی PNG کو 500KB تک پہنچنے کے لیے ابعاد میں بھاری کٹوتی چاہیے ہو سکتی ہے، جبکہ وہی تصویر JPG میں مکمل ریزولوشن پر آسانی سے فٹ ہو جاتی ہے۔ PNG صرف شفافیت چاہنے والے گرافکس کے لیے رکھیں۔"},{"question":"کیا 500KB پر شفاف PNG کو گہرے پس منظر پر فلیٹ کر سکتا ہوں؟","answer":"جی ہاں، JPG میں بدلتے وقت آپ وہ پس منظر رنگ چن سکتے ہیں جس سے شفاف حصے بھرے جائیں۔ گہرا چارکول ان مصنوعات کے شاٹ کے لیے اچھا کام کرتا ہے جو گہرے صفحے پر بیٹھیں گے۔ نتیجہ درست لگے، یہ یقینی کرنے کے لیے پیش نظارہ جانچیں۔"},{"question":"کیا ویب سائٹ تصویر کے لیے 500KB بہت بڑا ہے؟","answer":"یہ اس پر منحصر ہے کہ صفحے پر کتنی تصویریں ہیں۔ ایک 500KB ہیرو تصویر ٹھیک ہے، مگر بیس 500KB تصویریں مل کر 10 MB بن جاتی ہیں۔ ہیرو کے لیے 500KB اور معاون تصویروں کے لیے 100KB یا 200KB استعمال کریں تاکہ صفحہ تیز رہے۔"}];
